<?php require 'includes/functions.php';$title='Join the community';require 'includes/header.php';?><section class="section narrow"><div class="eyebrow">YOUR KINDNESS STARTS HERE</div><h1>Join the table.</h1><p>Register as a donor or orphanage. Our admin will review your details.</p><form class="panel form-grid" method="post" action="<?=url('actions/auth-actions.php')?>"><?=csrf()?><input type="hidden" name="action" value="register"><label class="span2">I would like to<select name="role"><option value="donor">Donate food — individual, restaurant or caterer</option><option value="orphanage">Receive food — orphanage</option></select></label><?php input('Your name / Organisation name','name','text','','maxlength="100"');input('Email address','email','email','','maxlength="190"');input('Phone number','phone','tel','','pattern="[0-9+ ()-]{7,20}" maxlength="20"');input('City','city','text','','maxlength="100"');?><label class="span2">Address<textarea name="address" required maxlength="500"></textarea></label><?php input('Password (at least 8 characters)','password','password','','minlength="8" autocomplete="new-password"');input('Confirm password','confirm_password','password','','minlength="8" autocomplete="new-password"');?><button class="button span2">Create account <?=icon('arrow')?></button></form><p>Already registered? <a href="<?=url('login.php')?>">Log in</a></p></section><?php require 'includes/footer.php';?>